#include "ksEditAddressTask.h"
#include <cstdint>
#include <iostream>
#include <stdexcept>
#include <vector>
using T=ks::EditAddressTask;using S=T::Stage;using C=T::Child;using K=T::Kind;
void check(bool b,const char*m){if(!b)throw std::runtime_error(m);}int main(){try{uint64_t cases=0;auto verify=[&](unsigned kind,unsigned bank,unsigned row,unsigned field,unsigned delta,uint32_t base){T t{K(kind),uint8_t(delta)};uint32_t expectedAddress=0x85ec00u+uint8_t(bank-1)*64u,page=expectedAddress&0xffffff00u;uint8_t offset=uint8_t(expectedAddress);uint32_t rowOffset=uint8_t(row-1)*8u;uint32_t result=base+rowOffset+16;unsigned publishes=0;std::vector<unsigned>copied;while(!t.complete()&&!t.handoff()){if(t.awaitingChild()){if(t.child()==C::Address)check(t.resumeAddress(page,offset),"Edit page/offsetreply");else check(t.resumeRecord(result,uint16_t(rowOffset)),"Edit recordreply");continue;}auto read=[&](S s)->uint32_t{switch(s){case S::MapRead:case S::FieldReadSubindex:return field;case S::BankRead:case S::ClampRead:return bank;case S::RecordRead:return row;case S::RecordReadBase:return base;case S::LoadRead:return uint8_t(t.index()*17+bank);default:throw std::runtime_error("Unexpected editaddressread");}};auto write=[&](S s,uint32_t v){++publishes;if(s==S::MapPublish)check(v==uint8_t(field*5u-64),"Edit mapbyte");else if(s==S::LoadPublishEdit)check(v==0x1738eu+offset,"Edit buffer address");else{check(v==uint8_t(t.index()*17+bank),"Edit copieddata");copied.push_back(t.index());}};auto stage=t.stage();auto cost=t.nextClocks(6);check(cost&&t.advanceBefore(cost-1,read,write,[](S){return 6u;})==0&&stage==t.stage(),"Early editaddressdeadline");check(t.advanceBefore(cost,read,write,[](S){return 6u;})==cost,"Editaddress deadline");}
if(kind==0)check(publishes==1&&t.mapped()==uint8_t(field*5u-64),"Edit mapped output");else if(kind==1){check(publishes==257&&copied.size()==256&&t.record()==0x1738eu+offset,"Edit copycount/address");for(unsigned i=0;i<copied.size();++i)check(copied[i]==i,"Edit copyorder");}else if(kind==2)check(t.handoff()&&t.page()==page,"Edit commit page");else if(kind==3)check(t.page()==page&&t.offset()==offset,"Edit unsignedbank address");else if(kind==4)check(t.record()==result&&t.row()==rowOffset,"Edit rawrow address");else if(kind==5)check(t.record()==result+uint8_t(field*2u)+1&&t.limit()==0x1510eu+rowOffset+uint8_t(field*2u),"Edit field/limit wrappedindex");else{unsigned sum=uint8_t(bank+delta);unsigned expected=sum==0||sum>=128?1:sum>16?16:sum;check(t.bank()==expected,"Edit bytewrapbank clamp");}++cases;};for(unsigned bank=0;bank<256;++bank){for(unsigned delta=0;delta<256;++delta)verify(6,bank,0,0,delta,0);for(unsigned kind:{0u,1u,2u,3u})verify(kind,bank,bank,bank,0,0xfffffff0u);}for(unsigned row=0;row<256;++row)for(unsigned field=0;field<256;++field)for(uint32_t base:{0u,0xffa30001u,0xfffffff0u})verify(5,0,row,field,0,base);for(unsigned row=0;row<256;++row)for(uint32_t base:{0u,0xffa30001u,0xfffffff0u})verify(4,0,row,0,0,base);
std::cout<<"PASS: "<<cases<<" pure edit bank/page/map/load/record/field/clamp tasks, independent unsigned arithmetic/index/address/copy/limit oracles, typed child replies and early deadlines\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
